// ==========================================================================
// LIMPIEZA & MAPEO DE DATOS DE EXCEL 365 (REPORTE DE LICITACIONES)
// ==========================================================================
const items = $input.all();
const licitacionesProcesadas = [];

for (const item of items) {
  const row = item.json;

  // Columnas exactas de Microsoft Excel Online (REPORTE DE LICITACIONES):
  // A: AÑO
  // B: Mes
  // C: EMPR (LAB&MED)
  // D: INS (ISSS, MINSAL, etc.)
  // E: Cliente (Hospitales e Institutos)
  // F: TIPO DE PROCESO (LICITACION COMPETITIVA, SUBASTA, BAJA CUANTIA)
  // G: No. Oferta (LC26DM0076, etc.)
  // H: Nombre Oferta
  // I: Presentación / Monto / Estado

  const anio = (row['AÑO'] || row['Año'] || row['ANIO'] || '2026').toString().trim();
  const mes = (row['Mes'] || row['MES'] || '').toString().trim().toUpperCase();
  const empresa = (row['EMPR'] || row['Empresa'] || 'LAB&MED').toString().trim().toUpperCase();
  const institucion = (row['INS'] || row['Institución'] || row['Institucion'] || 'MINSAL').toString().trim().toUpperCase();
  const cliente = (row['Cliente'] || row['CLIENTE'] || '').toString().trim();
  const tipoProceso = (row['TIPO DE PROCESO'] || row['Tipo Proceso'] || 'LICITACIÓN').toString().trim().toUpperCase();
  const numOferta = (row['No. Oferta'] || row['No Oferta'] || row['Oferta'] || '').toString().trim();
  const nombreOferta = (row['Nombre Oferta'] || row['Nombre de Oferta'] || row['Descripción'] || '').toString().trim();
  const presentacion = (row['Presentación'] || row['Presentacion'] || '').toString().trim();

  if (!numOferta && !nombreOferta && !cliente) continue;

  licitacionesProcesadas.push({
    json: {
      anio,
      mes,
      empresa,
      institucion,
      cliente,
      tipo_proceso: tipoProceso,
      numero_oferta: numOferta,
      nombre_oferta: nombreOferta,
      presentacion,
      fuente: 'Excel 365 SharePoint: REPORTE DE LICITACIONES',
      fecha_registro: new Date().toISOString()
    }
  });
}

return licitacionesProcesadas;

// ==========================================================================
// GESTIÓN DE MEMORIA ESTÁTICA & TRANSFORMACIÓN DBlabymed (Google Sheets)
// ==========================================================================
const staticData = $getWorkflowStaticData('global');
staticData.processedIds = staticData.processedIds || {};

const MAX_MEMORY_KEYS = 5000;
const storedKeys = Object.keys(staticData.processedIds);
if (storedKeys.length > MAX_MEMORY_KEYS) {
  const toDelete = storedKeys.slice(0, storedKeys.length - 2000);
  toDelete.forEach(k => delete staticData.processedIds[k]);
}

const items = $input.all();
const pedidosProcesados = [];

for (const item of items) {
  const row = item.json;
  const pedidoId = (row['PedidoID'] || row['A'] || row['ID'] || '').toString().trim();
  const fechaStr = (row['Fecha'] || row['FECHA'] || row['G'] || '').toString().trim();
  const detalle = (row['Detalle'] || row['Comentario'] || row['H'] || '').toString().trim();
  const archivoPdf = (row['Archivo'] || row['PDF'] || row['I'] || '').toString().trim();
  const usuarioId = (row['UsuarioID'] || row['Usuario'] || row['K'] || 'US-GENERAL').toString().trim();
  const ciudad = (row['Ciudad'] || row['Municipio'] || row['L'] || 'SAN SALVADOR').toString().trim().toUpperCase();
  const region = (row['Region'] || row['Región'] || row['M'] || 'CENTRAL').toString().trim().toUpperCase();

  if (!pedidoId && !detalle && !fechaStr) continue;

  const textoCompleto = `${detalle} ${archivoPdf}`.toLowerCase();
  const esUrgente = textoCompleto.includes('urgencia') || textoCompleto.includes('urgente') || textoCompleto.includes('hoy') || textoCompleto.includes('mañana');
  const esCreditoFiscal = textoCompleto.includes('crédito') || textoCompleto.includes('credito fiscal');
  const tienePdfAdjunto = archivoPdf.toLowerCase().includes('.pdf') || archivoPdf.includes('PedidosInfo_Files_');

  let fechaNormalizada = fechaStr;
  if (fechaStr.includes('/')) {
    const parts = fechaStr.split('/');
    if (parts.length === 3) {
      const d = parts[0].padStart(2, '0');
      const m = parts[1].padStart(2, '0');
      const y = parts[2].length === 2 ? '20' + parts[2] : parts[2];
      fechaNormalizada = `${y}-${m}-${d}`;
    }
  }

  const idKey = pedidoId || `${fechaNormalizada}_${usuarioId}_${ciudad}`;
  const esNuevo = !staticData.processedIds[idKey];
  staticData.processedIds[idKey] = new Date().toISOString();

  pedidosProcesados.push({
    json: {
      pedido_id: pedidoId || `PED-${Math.random().toString(36).substring(7).toUpperCase()}`,
      fecha: fechaNormalizada || new Date().toISOString().split('T')[0],
      detalle,
      archivo_pdf: archivoPdf,
      tiene_pdf_adjunto: tienePdfAdjunto,
      usuario_id: usuarioId,
      ciudad,
      region,
      es_urgente: esUrgente,
      es_credito_fiscal: esCreditoFiscal,
      estado: esUrgente ? 'Prioritario / Urgente' : 'En Proceso',
      es_nuevo_registro: esNuevo
    }
  });
}

return pedidosProcesados;

// ==========================================================================
// UNIFICADOR & MOTOR DE ANALYTICS CONSOLIDADO (PEDIDOS + LICITACIONES EXCEL)
// ==========================================================================
const pedidos = $('3a. Transformar Columnas Reales & Control Memoria').all().map(i => i.json);
let licitaciones = [];
try {
  licitaciones = $('3b. Transformar Licitaciones Excel 365').all().map(i => i.json);
} catch (e) {}

// 1. Métricas de Pedidos / Logística
const totalPedidos = pedidos.length;
const totalUrgentes = pedidos.filter(p => p.es_urgente).length;
const totalConPdf = pedidos.filter(p => p.tiene_pdf_adjunto).length;
const totalCreditoFiscal = pedidos.filter(p => p.es_credito_fiscal).length;

// 2. Métricas de Licitaciones Excel 365
const totalLicitaciones = licitaciones.length;
const porInstitucion = {};
const porTipoProceso = {};

licitaciones.forEach(lic => {
  const ins = lic.institucion || 'OTRAS';
  porInstitucion[ins] = (porInstitucion[ins] || 0) + 1;

  const tipo = lic.tipo_proceso || 'LICITACION';
  porTipoProceso[tipo] = (porTipoProceso[tipo] || 0) + 1;
});

return [{
  json: {
    timestamp_sync: new Date().toISOString(),
    kpis_pedidos: {
      total_pedidos: totalPedidos,
      total_urgentes: totalUrgentes,
      total_con_pdf: totalConPdf,
      total_credito_fiscal: totalCreditoFiscal
    },
    kpis_licitaciones_excel: {
      total_licitaciones: totalLicitaciones,
      por_institucion: porInstitucion,
      por_tipo_proceso: porTipoProceso
    },
    muestras_licitaciones: licitaciones.slice(0, 30),
    pedidos_recientes: pedidos.slice(-30).reverse()
  }
}];
